import { BrainIcon, ChevronDownIcon, DotIcon } from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import { createContext, memo, useContext, useMemo } from 'react';
import type { ComponentProps, ReactNode } from 'react';
import { useOpenState } from '@/components/ai-elements/use-open-state';
import { Badge } from '@/components/ui/badge';
import {
    Collapsible,
    CollapsibleContent,
    CollapsibleTrigger,
} from '@/components/ui/collapsible';
import { cn } from '@/lib/utils';

/*
 * AI Elements `chain-of-thought` (registry.ai-sdk.dev). Changes from the
 * registry copy: the open state uses `useOpenState` instead of Radix's internal
 * `useControllableState`; the header has no hard-coded default label.
 */

type ChainOfThoughtContextValue = {
    isOpen: boolean;
    setIsOpen: (open: boolean) => void;
};

const ChainOfThoughtContext = createContext<ChainOfThoughtContextValue | null>(
    null,
);

const useChainOfThought = () => {
    const context = useContext(ChainOfThoughtContext);

    if (!context) {
        throw new Error(
            'ChainOfThought components must be used within ChainOfThought',
        );
    }

    return context;
};

export type ChainOfThoughtProps = ComponentProps<'div'> & {
    open?: boolean;
    defaultOpen?: boolean;
    onOpenChange?: (open: boolean) => void;
};

export const ChainOfThought = memo(
    ({
        className,
        open,
        defaultOpen = false,
        onOpenChange,
        children,
        ...props
    }: ChainOfThoughtProps) => {
        const [isOpen, setIsOpen] = useOpenState(
            open,
            defaultOpen,
            onOpenChange,
        );

        const chainOfThoughtContext = useMemo(
            () => ({ isOpen, setIsOpen }),
            [isOpen, setIsOpen],
        );

        return (
            <ChainOfThoughtContext.Provider value={chainOfThoughtContext}>
                <div
                    className={cn('not-prose space-y-4', className)}
                    {...props}
                >
                    {children}
                </div>
            </ChainOfThoughtContext.Provider>
        );
    },
);

export type ChainOfThoughtHeaderProps = ComponentProps<
    typeof CollapsibleTrigger
>;

export const ChainOfThoughtHeader = memo(
    ({ className, children, ...props }: ChainOfThoughtHeaderProps) => {
        const { isOpen, setIsOpen } = useChainOfThought();

        return (
            <Collapsible onOpenChange={setIsOpen} open={isOpen}>
                <CollapsibleTrigger
                    className={cn(
                        'flex w-full items-center gap-2 text-sm text-muted-foreground transition-colors hover:text-foreground',
                        className,
                    )}
                    {...props}
                >
                    <BrainIcon className="size-4" />
                    <span className="flex-1 text-left">{children}</span>
                    <ChevronDownIcon
                        className={cn(
                            'size-4 transition-transform',
                            isOpen ? 'rotate-180' : 'rotate-0',
                        )}
                    />
                </CollapsibleTrigger>
            </Collapsible>
        );
    },
);

export type ChainOfThoughtStepProps = ComponentProps<'div'> & {
    icon?: LucideIcon;
    label: ReactNode;
    description?: ReactNode;
    status?: 'complete' | 'active' | 'pending';
};

export const ChainOfThoughtStep = memo(
    ({
        className,
        icon: Icon = DotIcon,
        label,
        description,
        status = 'complete',
        children,
        ...props
    }: ChainOfThoughtStepProps) => {
        const statusStyles = {
            complete: 'text-muted-foreground',
            active: 'text-foreground',
            pending: 'text-muted-foreground/50',
        };

        return (
            <div
                className={cn(
                    'flex gap-2 text-sm',
                    statusStyles[status],
                    'animate-in fade-in-0 slide-in-from-top-2',
                    className,
                )}
                {...props}
            >
                <div className="relative mt-0.5">
                    <Icon className="size-4" />
                    <div className="absolute top-7 bottom-0 left-1/2 -mx-px w-px bg-border" />
                </div>
                <div className="flex-1 space-y-2 overflow-hidden">
                    <div>{label}</div>
                    {description && (
                        <div className="text-xs text-muted-foreground">
                            {description}
                        </div>
                    )}
                    {children}
                </div>
            </div>
        );
    },
);

export type ChainOfThoughtSearchResultsProps = ComponentProps<'div'>;

export const ChainOfThoughtSearchResults = memo(
    ({ className, ...props }: ChainOfThoughtSearchResultsProps) => (
        <div
            className={cn('flex flex-wrap items-center gap-2', className)}
            {...props}
        />
    ),
);

export type ChainOfThoughtSearchResultProps = ComponentProps<typeof Badge>;

export const ChainOfThoughtSearchResult = memo(
    ({ className, children, ...props }: ChainOfThoughtSearchResultProps) => (
        <Badge
            className={cn('gap-1 px-2 py-0.5 text-xs font-normal', className)}
            variant="secondary"
            {...props}
        >
            {children}
        </Badge>
    ),
);

export type ChainOfThoughtContentProps = ComponentProps<
    typeof CollapsibleContent
>;

export const ChainOfThoughtContent = memo(
    ({ className, children, ...props }: ChainOfThoughtContentProps) => {
        const { isOpen } = useChainOfThought();

        return (
            <Collapsible open={isOpen}>
                <CollapsibleContent
                    className={cn(
                        'mt-2 space-y-3',
                        'text-popover-foreground outline-none data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:slide-out-to-top-2 data-[state=open]:animate-in data-[state=open]:slide-in-from-top-2',
                        className,
                    )}
                    {...props}
                >
                    {children}
                </CollapsibleContent>
            </Collapsible>
        );
    },
);

ChainOfThought.displayName = 'ChainOfThought';
ChainOfThoughtHeader.displayName = 'ChainOfThoughtHeader';
ChainOfThoughtStep.displayName = 'ChainOfThoughtStep';
ChainOfThoughtSearchResults.displayName = 'ChainOfThoughtSearchResults';
ChainOfThoughtSearchResult.displayName = 'ChainOfThoughtSearchResult';
ChainOfThoughtContent.displayName = 'ChainOfThoughtContent';

import { useCallback, useState } from 'react';

/**
 * Open state that a parent may control (`open` + `onOpenChange`) or leave to
 * the component (`defaultOpen`). Stands in for Radix's internal
 * `useControllableState`, which the AI Elements sources import directly.
 */
export function useOpenState(
    open: boolean | undefined,
    defaultOpen: boolean,
    onOpenChange?: (open: boolean) => void,
): [boolean, (open: boolean) => void] {
    const [uncontrolled, setUncontrolled] = useState(defaultOpen);
    const isControlled = open !== undefined;

    const setOpen = useCallback(
        (next: boolean) => {
            if (!isControlled) {
                setUncontrolled(next);
            }

            onOpenChange?.(next);
        },
        [isControlled, onOpenChange],
    );

    return [isControlled ? open : uncontrolled, setOpen];
}
